css:
/* 星图：昼夜双版（:root 为日间基线，[data-reader-theme="night"] 覆盖夜景）；正文区占页高 80%+（蓝图硬约束①） */
:root{
  --sc-bg:#f6f4ef; --sc-fg:#20242e; --sc-dim:#6c7385;
  --sc-gold:#8a6a12; --sc-line:rgba(138,106,18,.28);
}
[data-reader-theme="night"]{
  --sc-bg:#0a0c16; --sc-fg:#e8e6dd; --sc-dim:#8d92a8;
  --sc-gold:#e0bf63; --sc-line:rgba(224,191,99,.30);
}
html,body{margin:0;padding:0;background:var(--sc-bg);color:var(--sc-fg);
  font-family:"Noto Serif CJK SC","Source Han Serif SC",Georgia,serif;
  font-size:var(--md-font-size,18px);line-height:var(--md-line-height,1.9);}
.sc-head{position:relative;display:flex;justify-content:space-between;align-items:baseline;gap:.6em;
  padding:.6em 1.4em .5em;font-size:.74em;letter-spacing:.28em;color:var(--sc-dim);
  background-image:repeating-linear-gradient(90deg,var(--sc-line) 0 1px,transparent 1px 14px);
  background-size:100% 4px;background-position:bottom left;background-repeat:no-repeat;}
.sc-chapter{max-width:68%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.sc-pct{color:var(--sc-gold);letter-spacing:.08em;font-variant-numeric:tabular-nums;}
.sc-band{position:relative;height:12vh;padding:1em 1.4em 0;overflow:hidden;}
.sc-title{position:relative;z-index:1;font-size:1.6em;font-weight:650;letter-spacing:.16em;}
.sc-dial{position:absolute;right:1.4em;top:.55em;width:11vh;height:11vh;border-radius:50%;pointer-events:none;
  background:repeating-conic-gradient(from 0deg,var(--sc-line) 0deg .35deg,transparent .35deg 3deg),
    radial-gradient(circle,transparent 0 58%,var(--sc-line) 58% 59%,transparent 59% 74%,var(--sc-line) 74% 75%,transparent 75%);
  -webkit-mask-image:radial-gradient(circle,#000 0 78%,transparent 80%);mask-image:radial-gradient(circle,#000 0 78%,transparent 80%);}
.sc-dial::after{content:"";position:absolute;inset:34%;border:1px solid var(--sc-gold);border-radius:50%;}
.sc-body{position:relative;padding:.85em 1.4em 0;}
.sc-body .reader-chapter-title{margin:0 0 .75em;font-size:1.34em;font-weight:650;letter-spacing:.05em;}
.sc-body .reader-chapter-title::after{content:"✦";margin-left:.5em;color:var(--sc-gold);font-size:.7em;}
.sc-body .reader-paragraph{margin:0 0 .95em;text-indent:2em;}
.sc-body p{margin:0 0 .95em;}
.sc-body a{color:var(--sc-gold);text-decoration:none;border-bottom:1px solid var(--sc-line);}
.sc-body blockquote{margin:0 0 1.05em;padding:.45em .95em;border-left:2px solid var(--sc-gold);color:var(--sc-dim);}
.sc-body code{background:rgba(127,127,127,.14);padding:.13em .34em;border-radius:3px;}
.sc-body pre{background:rgba(127,127,127,.10);padding:.8em;border-radius:3px;overflow-x:auto;border:1px solid var(--sc-line);}
.sc-body table{width:100%;border-collapse:collapse;}
.sc-body th,.sc-body td{border:1px solid var(--sc-line);padding:.34em .55em;}
.sc-foot{position:relative;display:flex;justify-content:space-between;align-items:center;gap:.8em;
  padding:.5em 1.4em .8em;font-size:.7em;color:var(--sc-dim);font-variant-numeric:tabular-nums;}
.sc-foot-arc{width:2.6em;height:1.1em;border-bottom:1px solid var(--sc-gold);border-radius:0 0 100% 100%;opacity:.8;}
@media (prefers-reduced-motion:reduce){.sc-dial{background-position:0 0;}}
